			hint = "Ajude Theocritus a ver dentro da bastilha dos orcs.",
			text = [=[O Olho de {link:tower-of-azora}Azora{/link} mostrou a {link:theocritus}Theocritus{/link} um bruxo em guerra com os orcs que ele um dia ajudara. Por que os dois haviam rompido, nem o {link:magistrate-solomon}Magistrado Solomon{/link} sabia dizer. Para saber mais, o Alto Mago escondeu um glifo no alto da torre de vigia ao lado da {link:stonewatch-keep}Bastilha Mirante de Pedra{/link}, e começou a ler a mente dos orcs lá dentro.]=],
