			hint = "Faça o que Theocritus não está disposto a fazer ele mesmo.",
			text = [=[Por fim, {link:theocritus}Theocritus{/link} descobriu o que Morganth procurava: a Foice de Eluna. Temia que o bruxo já a tivesse encontrado, e que {link:stormwind-city}Ventobravo{/link} logo sentisse o seu poder. O Alto Mago não enfrentaria Morganth pessoalmente, então outro subiu a {link:tower-of-ilgalar}Torre de Ilgalar{/link} em seu lugar. O Pingente das Sombras de Morganth voltou a {link:elwynn-forest}Elwynn{/link}, e Theocritus declarou o reino salvo de um grave perigo.]=],
		},
	},
	mentions = {
