	aliases = { "clã Rocha Negra", "orcs Rocha Negra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os {link:blackrock-mountain}Rocha Negra{/link} são um dos clãs mais antigos e belicosos dos {link:orcs}orcs{/link}. Foram a espinha dorsal da antiga {link:horde}Horda{/link} e lhe deram dois de seus Chefes Guerreiros. Muito depois da derrota da Horda, os Rocha Negra mantiveram os velhos costumes de guerra, e nunca fizeram as pazes com os humanos.]=],
		},
		{
			title = "História",
			text = [=[Na {link:first-war}Primeira Guerra{/link}, o chefe Rocha Negra Blackhand liderou a {link:horde}Horda{/link} como seu Chefe Guerreiro, embora outros puxassem os fios por trás dele. Foi morto por um dos seus, {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, um guerreiro Rocha Negra que então levou a Horda à conquista de {link:stormwind-city}Ventobravo{/link}. Na {link:second-war}Segunda Guerra{/link}, a Horda de Doomhammer foi derrotada na {link:blackrock-mountain}Montanha Rocha Negra{/link}, depois de ele ter matado {link:anduin-lothar}Anduin Lothar{/link}. A maior parte dos orcs foi confinada em campos. Os Rocha Negra que escaparam se refugiaram na montanha que leva o seu nome, e desde então ocupam suas alturas.]=],
		},
		{
			title = "Em Cristarrubra",
			text = [=[Agora os {link:blackrock-mountain}Rocha Negra{/link} desceram das {link:burning-steppes}Estepes Ardentes{/link} para o sul. Sob o senhor da guerra {link:gath-ilzogg}Gath'Ilzogg{/link}, e com a magia sombria de {link:morganth}Morganth{/link}, tomaram a {link:stonewatch-keep}Bastilha Mirante de Pedra{/link} e derrubaram a ponte do {link:lake-everstill}Lago Plácido{/link}. Seus batedores armam emboscadas nas estradas, seus lançadores de sombras carregam orbes maculados por demônios, e seus campeões acampam junto ao desfiladeiro do norte. Outro bando de guerra entrou no extremo sudeste pelo {link:render-s-valley}Vale dos Laceradores{/link}. Mas avançaram tão fundo no reino que precisam buscar comida e armas nas colinas, e {link:lakeshire}Vila Plácida{/link} espera vencê-los pela fome.]=],
		},
		{
			title = "A Nova Horda",
			text = [=[Nem todo {link:blackrock-mountain}Rocha Negra{/link} ficou com o clã. {link:eitrigg}Eitrigg{/link}, que um dia serviu ao chefe guerreiro Rocha Negra, passou a odiar os adoradores de demônios que desviaram seu povo. Agora serve a {link:thrall}Thrall{/link} em {link:orgrimmar}Orgrimmar{/link}, longe da montanha de seu antigo clã.]=],
		},
	},
})

Translate("ptBR", "shadowhide-gnolls", {
	title = "Gnolls Umbrapele",
	aliases = { "gnolls Umbrapele", "Umbrapele" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Umbrapele são um clã de {link:gnolls}gnolls{/link} que habita o {link:galardell-valley}Vale Galardell{/link}, no nordeste de {link:redridge-mountains}Cristarrubra{/link}. Servem ao bruxo {link:morganth}Morganth{/link}. Seu líder é o {link:lieutenant-fangore}Tenente Fangore{/link}. Seus teceladores das trevas praticam uma magia sombria, seus assassinos atacam sem ser vistos, e seus matadores atacam orcs e humanos igualmente.]=],
		},
		{
			title = "Presos por Pingentes",
			text = [=[Cada Umbrapele usa um pingente através do qual {link:morganth}Morganth{/link} fala com eles. O Alto Mago {link:theocritus}Theocritus{/link} passou meses tentando alcançar esses pingentes. Conseguiu mandar uma mensagem através de alguns deles, e espera um dia mandar por eles um ataque que congele todos os gnolls que os usam.]=],
		},
		{
			title = "Sob a Lei",
			text = [=[O tribunal de {link:lakeshire}Vila Plácida{/link} declarou os Umbrapele culpados de ajudar um criminoso do reino, crime punido com a morte. O {link:bailiff-conacher}Meirinho Conacher{/link} paga por seus pingentes como prova, e o magistrado pôs uma recompensa pela cabeça do próprio {link:lieutenant-fangore}Fangore{/link}.]=],
		},
		{
			title = "Inimigos de Todos",
			text = [=[Os Umbrapele não são amigos dos {link:blackrock-mountain}Rocha Negra{/link}. Quando {link:morganth}Morganth{/link} se voltou contra seus aliados orcs, seus gnolls se voltaram com ele, e orcs morreram em suas mãos tão certamente quanto homens.]=],
		},
	},
})

Translate("ptBR", "redridge-gnolls", {
	title = "Gnolls Cristarrubra",
	aliases = { "gnolls Cristarrubra", "matilha Cristarrubra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os gnolls Cristarrubra são a antiga matilha de gnolls das {link:redridge-mountains}Montanhas Cristarrubra{/link}, distinta dos {link:shadowhide-gnolls}Umbrapele{/link} que servem a {link:morganth}Morganth{/link}. Não servem a nenhum bruxo e a nenhum {link:orcs}orc{/link}. Seus brutos e místicos percorrem as colinas ao norte de {link:lakeshire}Vila Plácida{/link}, e seus caçadores ilegais e vira-latas acampam ao longo da estrada do sul. Seu líder é {link:yowler}Yowler{/link}, que tem sua toca na {link:redridge-canyons}Garganta Cristarrubra{/link}, e cujo uivo chega até Vila Plácida.]=],
		},
		{
			title = "Seus Costumes",
			text = [=[Os gnolls Cristarrubra tomam o que a guerra deixa sem guarda. Apoderaram-se da caravana que levava ferro para a ponte do {link:lake-everstill}Lago Plácido{/link}. Roubam cavalos do estábulo de {link:lakeshire}Vila Plácida{/link}. Mudaram-se para as {link:rethban-caverns}Cavernas Retibanas{/link}, onde seus labutadores escavam o minério que a cidade antes extraía. São pouco organizados, mas respeitam a força acima de tudo. O {link:deputy-feldon}Delegado Feldon{/link} espera que a morte de seus debulhadores mais ferozes ensine os demais a ficar nas colinas. Em Rethban, um {link:gnolls}gnoll{/link} chamado Ardo Dirtpaw lidera a matilha que ocupa as cavernas.]=],
		},
	},
})
